Q: Populate an HTML Form from a FormData object A: <p>Using <a href="https://stackoverflow.com/a/44033425/1869660">this</a> and <a href="http://javascript-coder.com/javascript-form/javascript-form-value.phtml" rel="noreferrer">this</a>, here is how I serialize and deserialize form data:</p>

<pre><code>function formSerialize(form) {
    const data = new FormData(form);
    //https://stackoverflow.com/a/44033425/1869660
    return new URLSearchParams(data).toString();
}

function formDeserialize(form, data) {
    const entries = (new URLSearchParams(data)).entries();
    for(const [key, val] of entries) {
        //http://javascript-coder.com/javascript-form/javascript-form-value.phtml
        const input = form.elements[key];
        switch(input.type) {
            case 'checkbox': input.checked = !!val; break;
            default:         input.value = val;     break;
        }
    }
}
</code></pre>

<p><em>Warning: <code>formDeserialize()</code> won't clear fields that are not included in the stored data, e.g. empty radio groups or checkboxes. Also, not tested with all <code>&lt;input&gt;</code> types.</em></p>

